void apply_tone_mapping(float shift, float smooth) {
    const int TBLN = 256;
    float* lut = new float[TBLN];

    // Clamp shift and smooth to their respective ranges
    shift = std::clamp(shift, 0.25f, 8.0f);
    smooth = std::clamp(smooth, 0.0f, 1.0f);

    // Compute the LUT based on the shift value
    for (int i = 0; i < TBLN; ++i) {
        float x = static_cast<float>(i) / 255.0f;
        float adjusted_x = x * shift;

        if (shift >= 1.0f) {
            // Use a linear scaling
            lut[i] = adjusted_x;
        } else {
            // Use a cubic function for compression
            float y = adjusted_x / (1.0f + adjusted_x * (1.0f - smooth));
            lut[i] = y;
        }
    }

    // Apply the LUT to each pixel in the image data
    for (size_t i = 0; i < C.image_data.size(); ++i) {
        int value = static_cast<int>(C.image_data[i]);
        C.image_data[i] = lut[value];
    }

    // Update the maximum data values in the context object C based on the LUT
    float max_value = *std::max_element(lut, lut + TBLN);
    C.max_data_value = max_value;

    // Free the allocated memory for the LUT
    delete[] lut;
}

void applyToneMapping(float shift, float smooth) {
    // Clamp the shift and smooth parameters to their respective ranges
    shift = std::clamp(shift, 0.25f, 8.0f);
    smooth = std::clamp(smooth, 0.0f, 1.0f);

    const int TBLN = 256;
    float* lut = new float[TBLN];

    // Compute the lookup table (LUT)
    for (int i = 0; i < TBLN; ++i) {
        float x = static_cast<float>(i) / (TBLN - 1);
        if (shift == 1.0f) {
            // Linear scaling when shift is 1.0
            lut[i] = x;
        } else {
            // Cubic function for tone mapping
            float x_shifted = x * shift;
            float x_cubed = x_shifted * x_shifted * x_shifted;
            float adjusted = x_cubed / (x_shifted * x_shifted + smooth);
            lut[i] = adjusted;
        }
    }

    // Apply the LUT to each pixel in the image data
    for (size_t i = 0; i < C.imageData.size(); ++i) {
        float pixelValue = C.imageData[i];
        int index = static_cast<int>(pixelValue * (TBLN - 1));
        C.imageData[i] = lut[index];
    }

    // Update the maximum data values in the context object
    for (float val : C.imageData) {
        C.maxDataValue = std::max(C.maxDataValue, val);
    }

    // Free the allocated memory for the LUT
    delete[] lut;
}

