void apply_tone_mapping(float shift, float smooth) {
    // Clamp input parameters to their valid ranges
    shift = std::clamp(shift, 0.25f, 8.0f);
    smooth = std::clamp(smooth, 0.0f, 1.0f);

    const int TBLN = 256;
    float lut[TBLN];

    // Compute lookup table based on shift and smooth
    for (int i = 0; i < TBLN; ++i) {
        float x = i / 255.0f;
        float s = x * shift;
        if (shift <= 1.0f) {
            // Linear scaling
            lut[i] = s;
        } else {
            // Cubic scaling
            lut[i] = s * (1.0f - smooth) + x * smooth;
        }
