    // Apply LUT to each pixel in image data
    for (size_t i = 0; i < C->data_size; ++i) {
        float val = C->data[i];
        if (val >= 0 && val < TBLN) {
            C->data[i] = lut[(int)val];
        }
    }

    // Update max data values in context
    C->max_data = lut[255];

    // Free LUT memory (already in stack scope, so no free needed)
