void applyToneMapping(float shift, float smooth) {
    // Clamp shift and smooth to their valid ranges
    shift = std::clamp(shift, 0.25f, 8.0f);
    smooth = std::clamp(smooth, 0.0f, 1.0f);

    // Allocate the lookup table (LUT)
    const int TBLN = 256;
    float* lut = new float[TBLN];

    // Compute LUT values
    for (int i = 0; i < TBLN; ++i) {
        float x = static_cast<float>(i) / (TBLN - 1);
        float scaledX = x * shift;

        if (shift <= 1.0f) {
            // Linear scaling
            lut[i] = scaledX;
        } else {
            // Cubic function for tone mapping
            float denominator = 1.0f + std::pow(scaledX, 2.0f);
            lut[i] = scaledX / denominator * (1.0f + smooth);
        }
    }

    // Apply LUT to image data
    for (int y = 0; y < C.height; ++y) {
        for (int x = 0; x < C.width; ++x) {
            int pixelIndex = y * C.width + x;
            float pixelValue = C.imageData[pixelIndex];
            C.imageData[pixelIndex] = lut[(int)(pixelValue * (TBLN - 1))];
        }
    }

    // Update max data value in context object
    C.maxDataValue = lut[TBLN - 1];

    // Free the allocated memory
    delete[] lut;
}
